INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`) VALUES
(41761, 'ruRU', 'Сбор зимних лосей', 'Спасите 4 талбуков на ферме Куурос.', 'Мой отец, Карман, владеет этой фермой, и наш основной скот — талбуки. Должно быть, один из подлингов открыл ворота их загона, и они все разбежались!$B$BЭти маленькие ужасы могли бы перебить их прямо в клетке, но они любят охотиться на свою добычу. Боюсь, если я останусь здесь подольше, я стану их следующей трапезой!$B$BСоберёшь талбуков и приведёшь их сюда? Я сама не могу их поймать, и нельзя, чтобы отец узнал об этом!'),
(41816, 'ruRU', 'ОПАСНО: Обдоб Громила', '', ''),
(41824, 'ruRU', 'РАЗЫСКИВАЕТСЯ: Арру', '', ''),
(41828, 'ruRU', 'РАЗЫСКИВАЕТСЯ: Колючая Дубина', '', '');
